<li id="ability-discoveries-fake-fn-31-target"><p><Link to="/source/pathfinder_123_the_flooded_cathedral">Pathfinder #123: The Flooded Cathedral</Link> <InnerLink aria-label="Back to reference 31" id="backlink-ability-discoveries-fake-fn-31" data-hash-target to="ability-discoveries-fake-fn-31">↩</InnerLink> <InnerLink aria-label="Back to reference 31" id="backlink-ability-discoveries-fake-fn-31.2" data-hash-target to="ability-discoveries-fake-fn-31.2">↩<sup>2</sup></InnerLink> <InnerLink aria-label="Back to reference 31" id="backlink-ability-discoveries-fake-fn-31.3" data-hash-target to="ability-discoveries-fake-fn-31.3">↩<sup>3</sup></InnerLink> <InnerLink aria-label="Back to reference 31" id="backlink-ability-discoveries-fake-fn-31.4" data-hash-target to="ability-discoveries-fake-fn-31.4">↩<sup>4</sup></InnerLink></p></li>
